const RULE_MAP = {
  "Sierpinski nested pyramids": 90,
  "Crystalline diagonal fabric": 18,
  "Cascading chevron weave": 22,
  "Aperiodic chaotic drift": 30,
  "Soliton particle collisions": 110,
  "Dense turbulent static": 73
};
const WARP_MAP = {
  "Direct vertical strata": 0,
  "Gentle geological tilt": 1,
  "Curving barrel folds": 2,
  "Toroidal magnetic shear": 3,
  "Vortex spiral unwind": 4,
  "Logarithmic helix crawl": 5
};
const MUTATION_MAP = {
  "Pure pristine logic": 0.0,
  "Faint drift sparks": 0.005,
  "Leaking neon fissures": 0.02,
  "Pollen cloud dispersal": 0.05,
  "Violent rule shearing": 0.1,
  "Total cascade breakdown": 0.2
};
const PALETTE_MAP = {
  "Midnight basalt and emerald": ['#050510', '#00ff66'],
  "Deep ocean bioluminescence": ['#001122', '#00aaff'],
  "Oxidized copper patina": ['#332211', '#44cca8'],
  "Solar flare amber": ['#220500', '#ff6600'],
  "Iridescent oil slick": ['#111111', '#ff00ff'],
  "Monochrome bone fossil": ['#1a1a1a', '#e6e4d5']
};
const TEMPO_MAP = {
  "Sub-surface creep": 0.1,
  "Glacial sedimentation": 0.25,
  "Steady mechanical feed": 1.0,
  "Rhythmic pulsing surge": 2.0,
  "Rapid arterial flow": 3.0,
  "Torrential cascade": 4.0
};

p.setup = function() {
  p.createCanvas(800, 800);
  p.caBuf = p.createGraphics(200, 200);
  p.caBuf.noSmooth();

  p.history = new Uint8Array(200 * 200);
  p.cells = new Array(200).fill(0);
  p.cells[100] = 1;

  let bg = p.color('#050510');
  let fg = p.color('#00ff66');
  p.caBuf.background(bg);
  p.caBuf.fill(fg);
  p.caBuf.noStroke();

  for(let y = 0; y < 200; y++) {
    let nextCells = new Array(200).fill(0);
    for(let i = 0; i < 200; i++) {
      let left = p.cells[(i - 1 + 200) % 200];
      let me = p.cells[i];
      let right = p.cells[(i + 1) % 200];
      let state = (left << 2) | (me << 1) | right;
      let newState = (90 >> state) & 1;

      nextCells[i] = newState;
      p.history[y * 200 + i] = newState;
      if (newState === 1) p.caBuf.rect(i, y, 1, 1);
    }
    p.cells = nextCells;
  }

  p.yHead = 0;
  p.accum = 0;
  p.lastRule = "Sierpinski nested pyramids";
  p.lastPalette = "Midnight basalt and emerald";
};

p.draw = function() {
  const ruleText = p.getSynthVar('strata_rule') || "Sierpinski nested pyramids";
  const warpText = p.getSynthVar('growth_warp') || "Direct vertical strata";
  const mutText = p.getSynthVar('mutation_bleed') || "Pure pristine logic";
  const palText = p.getSynthVar('fossil_palette') || "Midnight basalt and emerald";
  const tempoText = p.getSynthVar('scroll_tempo') || "Sub-surface creep";

  const rule = RULE_MAP[ruleText];
  const warp = WARP_MAP[warpText];
  const mut = MUTATION_MAP[mutText];
  const pal = PALETTE_MAP[palText];
  let speed = TEMPO_MAP[tempoText];

  if (tempoText === "Rhythmic pulsing surge") {
     speed = (p.frameCount % 60 < 20) ? 3.0 : 0.5;
  }

  if (palText !== p.lastPalette) {
    let bgCol = p.color(pal[0]);
    let fgCol = p.color(pal[1]);
    p.caBuf.loadPixels();
    for (let i = 0; i < 40000; i++) {
      let col = p.history[i] ? fgCol : bgCol;
      let idx = i * 4;
      p.caBuf.pixels[idx] = p.red(col);
      p.caBuf.pixels[idx+1] = p.green(col);
      p.caBuf.pixels[idx+2] = p.blue(col);
      p.caBuf.pixels[idx+3] = 255;
    }
    p.caBuf.updatePixels();
    p.lastPalette = palText;
  }

  if (ruleText !== p.lastRule && p.lastRule !== null) {
    for(let i = 0; i < 200; i++) {
      if(p.random() < 0.3) p.cells[i] = 1;
    }
    p.lastRule = ruleText;
  }

  p.accum += speed;
  let updates = p.floor(p.accum);
  p.accum -= updates;

  if (updates > 0) {
    p.caBuf.noStroke();
    for (let k = 0; k < updates; k++) {
      p.caBuf.fill(pal[0]);
      p.caBuf.rect(0, p.yHead, 200, 1);

      p.caBuf.fill(pal[1]);
      let nextCells = new Array(200).fill(0);
      for (let i = 0; i < 200; i++) {
        let left = p.cells[(i - 1 + 200) % 200];
        let me = p.cells[i];
        let right = p.cells[(i + 1) % 200];
        let state = (left << 2) | (me << 1) | right;
        let newState = (rule >> state) & 1;

        if (mut > 0 && p.random() < mut) newState = 1 - newState;

        nextCells[i] = newState;
        p.history[p.yHead * 200 + i] = newState;
        if (newState === 1) p.caBuf.rect(i, p.yHead, 1, 1);
      }
      p.cells = nextCells;
      p.yHead = (p.yHead + 1) % 200;
    }
  }

  p.background(pal[0]);
  p.push();
  p.translate(400, 400);

  for (let i = 0; i < 200; i++) {
    let bufY = (p.yHead + i) % 200;
    let normY = i / 200;
    let logY = (i - 100) * 4; 

    p.push();
    if (warp === 0) {
      p.translate(0, logY);
      p.scale(4, 4);
    } else if (warp === 1) {
      p.rotate(p.PI / 8);
      p.translate(0, logY * 1.2);
      p.scale(5, 5);
    } else if (warp === 2) {
      let xOff = p.sin(normY * p.PI * 4 + p.frameCount * 0.05) * 80;
      p.translate(xOff, logY);
      p.scale(4, 4);
    } else if (warp === 3) {
      let theta = p.frameCount * 0.01 + normY * p.PI * 4;
      p.rotate(theta);
      p.translate(0, normY * 300 - 100);
      p.scale(4 + normY * 2, 4);
    } else if (warp === 4) {
      p.rotate(normY * p.PI * 6 + p.frameCount * 0.02);
      p.translate(0, logY * (0.5 + normY));
      p.scale(1 + normY * 8, 4);
    } else if (warp === 5) {
      p.rotate(p.log(normY + 0.1) * 8 - p.frameCount * 0.03);
      p.translate(0, logY * 1.5);
      p.scale(2 + normY * 6, 4);
    }

    p.image(p.caBuf, -100, -0.5, 200, 1.5, 0, bufY, 200, 1);
    p.pop();
  }
  p.pop();
};
